-- Observe only the final, audited invoice state: carried credits are inserted before issuance.
CREATE TRIGGER nc_webhook_settled_issue AFTER INSERT ON nc_audit WHEN NEW.action='invoice.issue' BEGIN
INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),'invoice.paid',i.customer_id,i.id,json_object('type','invoice.paid','data',json_object('id',i.id,'invoice_id',i.id,'customer_id',i.customer_id,'amount_cents',i.total_cents,'cash_allocated_cents',COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id=i.id),0),'custody','recorded-ledger-settlement'),'metadata',json_array(json_object('kind','customer','id',i.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=i.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',i.subscription_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=i.subscription_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',i.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=i.id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=i.id),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN(SELECT price_id FROM nc_items WHERE subscription_id=i.subscription_id UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=i.id AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER) FROM nc_invoices i
 WHERE (i.id=NEW.subject AND (i.status='issued' AND i.total_cents-COALESCE((SELECT SUM(COALESCE(applied_cents,amount_cents)) FROM nc_credit_notes WHERE invoice_id=i.id),0)-COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id=i.id),0)-COALESCE((SELECT SUM(amount_cents) FROM nc_usage_credit_applications WHERE invoice_id=i.id),0)-COALESCE((SELECT SUM(amount_cents) FROM nc_balance_entries WHERE invoice_id=i.id AND kind='application' AND grant_id IS NOT NULL),0)=0) AND NOT EXISTS(SELECT 1 FROM nc_webhook_invoice_settlements m WHERE m.invoice_id=i.id)) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=i.customer_id AND erased_at IS NOT NULL);
INSERT OR IGNORE INTO nc_webhook_invoice_settlements(invoice_id,customer_id) SELECT i.id,i.customer_id FROM nc_invoices i WHERE i.id=NEW.subject AND (i.status='issued' AND i.total_cents-COALESCE((SELECT SUM(COALESCE(applied_cents,amount_cents)) FROM nc_credit_notes WHERE invoice_id=i.id),0)-COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id=i.id),0)-COALESCE((SELECT SUM(amount_cents) FROM nc_usage_credit_applications WHERE invoice_id=i.id),0)-COALESCE((SELECT SUM(amount_cents) FROM nc_balance_entries WHERE invoice_id=i.id AND kind='application' AND grant_id IS NOT NULL),0)=0) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1);
END;
